    def _write_playtest_ready_game(
        self,
        *,
        work_item: WorkItem,
        spec: GameProductionSpec,
    ) -> WorkItemResult:
        _remove_obsolete_game_files(spec.project_path)
        for relative_path, content in _playtest_ready_files(spec).items():
            _write_text(spec.project_path / relative_path, content)
        return WorkItemResult(
            status="done",
            summary="Playtest-ready game systems, interaction UI, and content pack generated.",
            artifacts=[
                _artifact(
                    work_item=work_item,
                    suffix="playtest-ready-game",
                    path=spec.project_path / "src",
                    supports=[
                        "playtest_ready_game",
                        "interaction_flow",
                        "content_pack",
                        "parent_report",
                    ],
                )
            ],
        )

    def _apply_benchmark_quality_iteration(
        self,
        *,
        work_item: WorkItem,
        spec: GameProductionSpec,
    ) -> WorkItemResult:
        """Push a playable first pass toward benchmark-level game feel.

        The previous production gate proved that KUN could ship a playable
        vertical slice.  This phase is deliberately different: it leaves the
        expression original, but adds benchmark-pressure systems that make the
        result behave more like a real word-to-world puzzle sandbox.
        """

        _write_text(spec.project_path / "src" / "engine" / "causalPhysics.ts", _causal_physics_ts())
        _write_text(spec.project_path / "scripts" / "long-playtest.mjs", _long_playtest_script())
        _upsert_package_script(
            spec.project_path / "package.json", "test:long", "node scripts/long-playtest.mjs"
        )
