def _remove_obsolete_game_files(project_path: Path) -> None:
    for relative_path in [
        "src/engine/mockAi.ts",
        "docs/mvp-scope.md",
        "docs/delivery-report.md",
        "docs/research-first-mvp-plan.md",
        "docs/game-design-spec.md",
        "docs/interaction-design.md",
        "docs/internal-playtest-plan.md",
    ]:
        path = project_path / relative_path
        if path.exists():
            path.unlink()


def _upsert_package_script(package_path: Path, script_name: str, command: str) -> None:
    payload = json.loads(package_path.read_text(encoding="utf-8"))
    scripts = payload.setdefault("scripts", {})
    scripts[script_name] = command
    _write_text(package_path, json.dumps(payload, ensure_ascii=False, indent=2) + "\n")


def _ensure_portless_static_browser_gate(spec: GameProductionSpec) -> None:
    """Install the static browser gate expected by the external supervisor."""

    template = (
        scribble_adventure_ready_files()
        if spec.production_mode == "scribble_adventure_functional_parity_v1"
        else scribble_parity_ready_files()
    )
    script = template.get("scripts/browser-static-playtest.mjs")
    if not script:
        return
    _write_text(spec.project_path / "scripts" / "browser-static-playtest.mjs", script)
    _upsert_package_script(
        spec.project_path / "package.json",
        "test:browser-static",
        "node scripts/browser-static-playtest.mjs",
    )


def _append_once(path: Path, content: str, *, marker: str) -> None:
    current = path.read_text(encoding="utf-8") if path.exists() else ""
    if marker in current:
        return
    _write_text(path, current.rstrip() + "\n" + content.lstrip())


