def _patch_word_to_world_for_semantic_synthesis(parser_path: Path) -> None:
    parser = parser_path.read_text(encoding="utf-8")
    if "semanticFallbackEntry" in parser and "semanticRuleHeuristics" in parser:
        return
    semantic_helpers = """
const semanticRuleHeuristics: Array<{ aliases: string[]; kind: string; families: string[]; sparkTags: SparkKey[] }> = [
  { aliases: ["桥", "路", "梯", "船", "车", "飞", "翅膀", "传送"], kind: "route-maker", families: ["crossing", "movement", "support"], sparkTags: ["science", "creativity"] },
  { aliases: ["灯", "光", "太阳", "月亮", "星", "火把", "镜"], kind: "light-maker", families: ["light", "reveal", "story"], sparkTags: ["science", "story"] },
  { aliases: ["朋友", "伙伴", "动物", "机器人", "精灵", "老师"], kind: "companion-maker", families: ["comfort", "social", "ask"], sparkTags: ["social", "story"] },
  { aliases: ["雨", "水", "冰", "云", "风", "伞", "冷"], kind: "weather-maker", families: ["weather", "cooling", "protect"], sparkTags: ["nature", "science"] },
  { aliases: ["钥匙", "工具", "修", "门", "锁", "机器"], kind: "tool-maker", families: ["unlock", "repair", "ask"], sparkTags: ["science", "aiCollaboration"] },
  { aliases: ["种子", "树", "花", "草", "果", "森林"], kind: "nature-maker", families: ["growth", "nature", "comfort"], sparkTags: ["nature", "creativity"] },
  { aliases: ["音乐", "歌", "鼓", "铃", "声音", "安静"], kind: "sound-maker", families: ["music", "comfort", "calm"], sparkTags: ["story", "social"] },
];

function normalizedCreativeName(input: string): string {
  const cleaned = input
    .replace(/为自造关卡准备/g, "")
    .replace(/我想|我要|请|帮我|帮助|一个|一只|一座|一把|可以|能够|需要|让|把/g, "")
    .replace(/[，。！？、,.!?\\s]/g, "");
  return cleaned.slice(0, 12) || "想象物件";
}

function semanticFallbackEntry(input: string, worldId: WorldId): VocabularyEntry {
  const matches = semanticRuleHeuristics.filter((entry) => includesAny(input, entry.aliases));
  const families = Array.from(new Set(matches.flatMap((entry) => entry.families)));
  const sparkTags = Array.from(new Set(matches.flatMap((entry) => entry.sparkTags)));
  const seed = matches[0] ?? semanticRuleHeuristics[(worldId.length + input.length) % semanticRuleHeuristics.length];
  const name = normalizedCreativeName(input);
  return {
    kind: `semantic-${seed.kind}`,
    aliases: [name],
    defaultName: name.endsWith("造物") ? name : name,
    ruleFamilies: families.length ? families : [...seed.families],
    sparkTags: sparkTags.length ? sparkTags : [...seed.sparkTags],
  };
}

"""
    parser = _replace_once(
        parser,
        """export function objectFromVocabulary(input: string, worldId: WorldId): VocabularyEntry {
  return objectVocabulary.find((entry) => includesAny(input, entry.aliases))
    ?? objectVocabulary[(worldId.length + input.length) % objectVocabulary.length];
}""",
        semantic_helpers
        + """export function objectFromVocabulary(input: string, worldId: WorldId): VocabularyEntry {
  return objectVocabulary.find((entry) => includesAny(input, entry.aliases))
    ?? semanticFallbackEntry(input, worldId);
}""",
    )
    _write_text(parser_path, parser)


