def _replace_once(source: str, old: str, new: str) -> str:
    if old not in source:
        return source
    return source.replace(old, new, 1)


def _patch_app_for_causal_lab(app_path: Path) -> None:
    app = app_path.read_text(encoding="utf-8")
    if "explainCausalOutcome" not in app:
        app = _replace_once(
            app,
            'import { applySpark, sparkLabels, summarizeSpark, topSpark } from "./engine/spark";',
            'import { applySpark, sparkLabels, summarizeSpark, topSpark } from "./engine/spark";\n'
            'import { explainCausalOutcome } from "./engine/causalPhysics";',
        )
    if "const causal = explainCausalOutcome" not in app:
        app = _replace_once(
            app,
            "      const result = applyObjectToWorld(worldId, before, object);",
            "      const result = applyObjectToWorld(worldId, before, object);\n"
            "      const causal = explainCausalOutcome(object, before.activeTags);",
        )
    app = _replace_once(
        app,
        "        feedback: result.feedback,",
        "        feedback: `${result.feedback} ${causal.summary}`,",
    )
    app = _replace_once(
        app,
        '<h2>背包</h2><div className="inventoryShelf">',
        '<h2>因果实验室</h2><div className="causalLab">{latest ? explainCausalOutcome(latest.object, activeState.activeTags).facts.map((fact) => <span key={fact}>{fact}</span>) : <span>生成物件后会显示重量、浮力、光照、连接和目标影响。</span>}</div><h2>背包</h2><div className="inventoryShelf">',
    )
    _write_text(app_path, app)


def _causal_physics_ts() -> str:
    return """import type { GeneratedObject } from "../types";

type CausalOutcome = {
  mass: "light" | "medium" | "heavy";
  motion: "static" | "rolling" | "floating" | "flying" | "bouncy";
  affordanceGraph: string[];
  facts: string[];
  summary: string;
};

function has(object: GeneratedObject, property: string): boolean {
  return object.properties.includes(property) || object.ruleFamilies.includes(property);
}

export function explainCausalOutcome(object: GeneratedObject, activeTags: string[] = []): CausalOutcome {
  const mass = has(object, "heavy") || has(object, "stone") || has(object, "metal")
    ? "heavy"
    : has(object, "lightweight") || has(object, "floating") || has(object, "flying")
      ? "light"
      : "medium";
  const motion = has(object, "flying")
    ? "flying"
    : has(object, "floating")
      ? "floating"
      : has(object, "bouncy")
        ? "bouncy"
        : object.ruleFamilies.includes("movement")
          ? "rolling"
          : "static";
  const affordanceGraph = [
    object.ruleFamilies.includes("crossing") || motion === "flying" || motion === "floating" ? "route" : "",
    object.ruleFamilies.includes("light") || has(object, "illuminating") ? "visibility" : "",
    object.ruleFamilies.includes("comfort") || has(object, "friendly") ? "npc-trust" : "",
    object.action === "combine" || object.action === "attach" ? "compound-tool" : "",
    activeTags.includes("unlocking") && object.ruleFamilies.includes("repair") ? "repair-chain" : "",
  ].filter(Boolean);
  const facts = [
    `重量:${mass}`,
    `运动:${motion}`,
    affordanceGraph.length ? `作用:${affordanceGraph.join("/")}` : "作用:观察/占位",
  ];
  return {
    mass,
    motion,
    affordanceGraph,
    facts,
    summary: `因果反馈：${object.name} 的${facts.join("，")}，可以继续用属性或组合改变解法。`,
  };
}
"""


def _long_playtest_script() -> str:
    return """import { existsSync, readFileSync, writeFileSync } from "node:fs";

const required = [
  "src/engine/causalPhysics.ts",
  "scripts/long-playtest.mjs",
  "docs/benchmark-quality-iteration.md"
];
for (const file of required) {
  if (!existsSync(file)) throw new Error(`Missing long-playtest requirement: ${file}`);
}

const app = readFileSync("src/App.tsx", "utf8");
const physics = readFileSync("src/engine/causalPhysics.ts", "utf8");
const styles = readFileSync("src/styles.css", "utf8");
const packageJson = JSON.parse(readFileSync("package.json", "utf8"));

const checks = [
  ["causal physics engine", physics.includes("affordanceGraph") && physics.includes("mass")],
  ["causal feedback integrated", app.includes("explainCausalOutcome") && app.includes("因果实验室")],
  ["gamefeel panel styled", styles.includes("causalLab")],
  ["long playtest script registered", packageJson.scripts?.["test:long"] === "node scripts/long-playtest.mjs"],
  ["original expression preserved", !app.includes("Maxwell") && !app.includes("Starite")]
];
const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
const report = { ok: failed.length === 0, checks: checks.map(([name]) => name), failed };
writeFileSync("docs/long-playtest-result.json", JSON.stringify(report, null, 2));
if (failed.length) {
  console.error(JSON.stringify(report, null, 2));
  process.exit(1);
}
console.log(JSON.stringify(report, null, 2));
"""


