def _internal_test_script() -> str:
    return """import { readFileSync, existsSync } from "node:fs";

const requiredFiles = [
  "src/App.tsx",
  "src/data/worlds.ts",
  "src/engine/mockAi.ts",
  "src/engine/safety.ts",
  "src/engine/spark.ts",
  "src/engine/storage.ts",
  "docs/interaction-design.md",
  "docs/internal-playtest-plan.md",
];

for (const file of requiredFiles) {
  if (!existsSync(file)) {
    throw new Error(`Missing required file: ${file}`);
  }
}

const app = readFileSync("src/App.tsx", "utf8");
const worlds = readFileSync("src/data/worlds.ts", "utf8");
const safety = readFileSync("src/engine/safety.ts", "utf8");
const packageJson = JSON.parse(readFileSync("package.json", "utf8"));

const checks = [
  ["children play tab", app.includes("儿童游玩")],
  ["parent report tab", app.includes("家长报告")],
  ["internal playtest tab", app.includes("内测路线")],
  ["safety redirect feedback", app.includes("安全重定向")],
  ["rainbow world", worlds.includes("彩虹造物岛")],
  ["story world", worlds.includes("故事星球")],
  ["playtest scenario data", worlds.includes("playtestScenarios")],
  ["danger terms", safety.includes("危险")],
  ["internal test script", packageJson.scripts["test:internal"] === "node scripts/internal-test.mjs"],
  ["user simulation script", packageJson.scripts["test:user-sim"] === "node scripts/user-sim.mjs"],
  ["scenario runner pins world", app.includes("submitTurn(scenario.sampleInput, scenario.worldId)")],
  ["submit turn accepts scenario world", app.includes("forcedWorldId?: WorldId")],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) {
  throw new Error(`Internal playtest checks failed: ${failed.join(", ")}`);
}

console.log(JSON.stringify({ ok: true, checks: checks.map(([name]) => name) }, null, 2));
"""


def _user_sim_script() -> str:
    return """import { readFileSync } from "node:fs";

const app = readFileSync("src/App.tsx", "utf8");
const storage = readFileSync("src/engine/storage.ts", "utf8");
const styles = readFileSync("src/styles.css", "utf8");

const checks = [
  ["fresh storage namespace", storage.includes("huohutu.spark.playtest.snapshot.v3")],
  ["does not load old playtest namespace", !storage.includes("huohutu.spark.playtest.snapshot.v2")],
  ["first-run coach exists", app.includes("firstRunCoach")],
  ["first-run copy exists", app.includes("第一次进入")],
  ["one-tap first utterance", app.includes("开始第一句话")],
  ["empty parent report state", app.includes("还没有记录。开始游玩后")],
  ["dynamic input placeholder", app.includes("placeholder={`孩子可以输入一句话，例如：${activeWorld.starterPrompts[0]}`}")],
  ["reset remains available", app.includes("重置本机体验") && app.includes("resetSnapshot()")],
  ["first-run styles exist", styles.includes(".firstRunCoach")],
  ["playtest routes remain explicit", app.includes("内测通过项")],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) {
  throw new Error(`User simulation checks failed: ${failed.join(", ")}`);
}

console.log(JSON.stringify({ ok: true, simulatedPersonas: ["new-child", "returning-parent", "internal-tester"], checks: checks.map(([name]) => name) }, null, 2));
"""


