def _safety_ts() -> str:
    return """import type { SafetyLevel } from "../types";

const blockedTerms = ["打人", "伤害", "杀", "血", "危险", "跳楼", "自杀", "炸", "毒", "裸", "枪"];

export function classifySafety(input: string): { level: SafetyLevel; reason: string } {
  const normalized = input.trim().toLowerCase();
  const blocked = blockedTerms.find((term) => normalized.includes(term));
  return blocked ? { level: "redirected", reason: blocked } : { level: "safe", reason: "" };
}

export function safeRewrite(reason: string): string {
  return reason ? "安全重定向：把危险想法改成保护朋友、修好世界或寻求帮助。" : "";
}
"""


def _mock_ai_ts() -> str:
    return """import { worlds } from "../data/worlds";
import type { AiTurnResult, SparkKey, WorldId, WorldState } from "../types";
import { classifySafety, safeRewrite } from "./safety";

const colorWords = ["红", "黄", "蓝", "绿", "紫", "粉", "橙", "彩虹", "金色", "银色"];
const weatherWords = ["雨", "风", "雪", "太阳", "晴", "云", "彩虹", "星光"];
const buildWords = ["桥", "门", "路", "房子", "塔", "船", "石头", "树", "云"];
const storyWords = ["故事", "然后", "因为", "结尾", "迷路", "遇到", "朋友", "门"];
const feelingWords = ["开心", "难过", "害怕", "孤单", "喜欢", "朋友", "帮", "安慰"];
const questionWords = ["为什么", "怎么", "什么", "哪里", "吗", "?"];

function includesAny(input: string, terms: string[]): boolean { return terms.some((term) => input.includes(term)); }
function uniqueTags(tags: SparkKey[]): SparkKey[] { return Array.from(new Set(tags)); }
function objectFromInput(input: string, worldId: WorldId): string {
  const color = colorWords.find((term) => input.includes(term));
  const build = buildWords.find((term) => input.includes(term));
  if (color && build) return `${color}${build}`;
  if (color) return `${color}光点`;
  if (build) return `会回应的${build}`;
  return worldId === "rainbow-island" ? "想法泡泡" : "故事碎片";
}

export function runMockAiTurn(params: { input: string; activeWorldId: WorldId; currentState: WorldState }): AiTurnResult {
  const { input, activeWorldId, currentState } = params;
  const safety = classifySafety(input);
  const world = worlds[activeWorldId];
  if (safety.level === "redirected") {
    const rewrite = safeRewrite(safety.reason);
    return {
      safetyLevel: "redirected",
      sparkTags: ["expression", "aiCollaboration"],
      worldDelta: { companionMood: "温柔守护", storyBeats: [...currentState.storyBeats.slice(-3), `${world.companion}把危险表达改成保护朋友的任务。`], interactionCount: currentState.interactionCount + 1 },
      reply: `${world.companion}听见你有很强的想法。${rewrite}我们把它变成修好世界、照顾伙伴的冒险吧。`,
    };
  }
  const tags: SparkKey[] = ["expression", "aiCollaboration"];
  if (includesAny(input, colorWords)) tags.push("creativity");
  if (includesAny(input, weatherWords)) tags.push("nature");
  if (includesAny(input, buildWords)) tags.push("science", "creativity");
  if (includesAny(input, storyWords)) tags.push("story");
  if (includesAny(input, feelingWords)) tags.push("social");
  if (includesAny(input, questionWords)) tags.push("science");
  if (input.length > 16) tags.push("story");
  const newObject = objectFromInput(input, activeWorldId);
  const weather = weatherWords.find((term) => input.includes(term)) ?? currentState.weather;
  const skyMood = colorWords.find((term) => input.includes(term)) ?? currentState.skyMood;
  const beat = activeWorldId === "rainbow-island"
    ? `${world.companion}把“${input}”变成了${newObject}，岛上的小路亮了一下。`
    : `${world.companion}把“${input}”接进冒险，${newObject}成为下一段故事线索。`;
  const reply = activeWorldId === "rainbow-island"
    ? `${world.companion}明白啦。${newObject}出现了。你还想让谁住进这里？`
    : `${world.companion}把这句话放进故事里了。${newObject}正在发光，我们继续问它一个为什么。`;
  return {
    reply,
    safetyLevel: "safe",
    sparkTags: uniqueTags([...world.sparkBias.slice(0, 1), ...tags]),
    worldDelta: { weather, skyMood, objects: [...currentState.objects.slice(-5), newObject], storyBeats: [...currentState.storyBeats.slice(-4), beat], companionMood: tags.includes("social") ? "被关心" : tags.includes("science") ? "想探索" : "开心", interactionCount: currentState.interactionCount + 1 },
  };
}
"""


def _spark_ts() -> str:
    return """import type { ChildEvent, SparkKey, SparkScores } from "../types";

export const sparkLabels: Record<SparkKey, string> = {
  expression: "表达火花",
  creativity: "创造火花",
  story: "故事火花",
  science: "探索火花",
  social: "共情火花",
  nature: "自然火花",
  aiCollaboration: "AI协作火花",
};
export const initialSparkScores: SparkScores = { expression: 2, creativity: 2, story: 2, science: 2, social: 2, nature: 2, aiCollaboration: 2 };
export function applySpark(scores: SparkScores, tags: SparkKey[]): SparkScores {
  const next = { ...scores };
  for (const tag of tags) next[tag] = Math.min(100, next[tag] + 8);
  return next;
}
export function topSpark(scores: SparkScores): SparkKey {
  return (Object.keys(scores) as SparkKey[]).sort((a, b) => scores[b] - scores[a])[0];
}
export function summarizeSpark(events: ChildEvent[], scores: SparkScores): string {
  if (events.length === 0) return "还没有开始冒险。等孩子第一次说出想法，Spark 轨迹就会出现。";
  const label = sparkLabels[topSpark(scores)];
  const recentTags = events.slice(0, 4).flatMap((event) => event.sparkTags);
  const hints = [
    `${label}目前最亮。`,
    recentTags.includes("story") ? "孩子正在尝试把角色、原因和结尾连起来。" : "",
    recentTags.includes("science") ? "孩子会问变化背后的为什么，适合继续给探索任务。" : "",
    recentTags.includes("social") ? "孩子开始关注伙伴感受，可以增加合作任务。" : "",
    recentTags.includes("creativity") ? "孩子喜欢改变世界外观，适合给开放创作任务。" : "",
  ].filter(Boolean);
  return hints.join(" ");
}
"""


def _storage_ts() -> str:
    return """import { initialWorldStates } from "../data/worlds";
import type { GameSnapshot } from "../types";
import { initialSparkScores } from "./spark";

const storageKey = "huohutu.spark.playtest.snapshot.v3";
export function createInitialSnapshot(): GameSnapshot {
  return { activeWorldId: "rainbow-island", ageBand: "5-6", worlds: initialWorldStates, sparkScores: initialSparkScores, completedTaskIds: [], events: [], cloudSyncEnabled: false, internalTestMode: true };
}
export function loadSnapshot(): GameSnapshot {
  try {
    const raw = window.localStorage.getItem(storageKey);
    return raw ? { ...createInitialSnapshot(), ...JSON.parse(raw) } as GameSnapshot : createInitialSnapshot();
  } catch {
    return createInitialSnapshot();
  }
}
export function saveSnapshot(snapshot: GameSnapshot): void { window.localStorage.setItem(storageKey, JSON.stringify(snapshot)); }
export function resetSnapshot(): GameSnapshot { const next = createInitialSnapshot(); saveSnapshot(next); return next; }
export async function syncToCloudAdapter(snapshot: GameSnapshot): Promise<{ ok: boolean; message: string }> {
  if (!snapshot.cloudSyncEnabled) return { ok: true, message: "云端同步未开启，当前只保存在本机。" };
  await new Promise((resolve) => window.setTimeout(resolve, 240));
  return { ok: true, message: "已进入云端同步队列。MVP 当前使用本地模拟接口。" };
}
"""


def _app_tsx() -> str:
    return """import { useEffect, useMemo, useState } from "react";
import { initialWorldStates, worlds } from "./data/worlds";
import { runMockAiTurn } from "./engine/mockAi";
import { applySpark, sparkLabels, summarizeSpark, topSpark } from "./engine/spark";
import { loadSnapshot, resetSnapshot, saveSnapshot, syncToCloudAdapter } from "./engine/storage";
import type { AgeBand, ChildEvent, GameSnapshot, PlaytestScenario, SparkKey, WorldId } from "./types";

const ageBands: Array<{ id: AgeBand; label: string; note: string }> = [
  { id: "2-4", label: "2-4岁", note: "短句表达" },
  { id: "5-6", label: "5-6岁", note: "任务探索" },
  { id: "7-9", label: "7-9岁", note: "共创故事" },
];
const sparkOrder: SparkKey[] = ["expression", "creativity", "story", "science", "social", "nature", "aiCollaboration"];

export default function App() {
  const [snapshot, setSnapshot] = useState<GameSnapshot>(() => loadSnapshot());
  const [input, setInput] = useState("");
  const [mode, setMode] = useState<"play" | "parent" | "test">("play");
  const [syncMessage, setSyncMessage] = useState("本机保存已开启");
  useEffect(() => saveSnapshot(snapshot), [snapshot]);
  const activeWorld = worlds[snapshot.activeWorldId];
  const activeWorldState = snapshot.worlds[snapshot.activeWorldId];
  const currentTasks = activeWorld.tasks.filter((task) => task.ageBands.includes(snapshot.ageBand));
  const topSparkKey = topSpark(snapshot.sparkScores);
  const hasStarted = snapshot.events.length > 0;
  const completedInWorld = useMemo(() => currentTasks.filter((task) => snapshot.completedTaskIds.includes(task.id)).length, [currentTasks, snapshot.completedTaskIds]);
  const playtestScenarios = (Object.values(worlds).flatMap((world) => world.playtestScenarios));
  const playtestChecks = [
    { label: "完成至少一次造物输入", ok: snapshot.events.some((event) => event.worldId === "rainbow-island") },
    { label: "完成至少一次叙事输入", ok: snapshot.events.some((event) => event.worldId === "story-planet") },
    { label: "触发安全重定向", ok: snapshot.events.some((event) => event.safetyLevel === "redirected") },
    { label: "家长报告有两条以上片段", ok: snapshot.events.length >= 2 },
  ];

  function updateSnapshot(mutator: (current: GameSnapshot) => GameSnapshot) { setSnapshot((current) => mutator(current)); }
  function submitTurn(text: string, forcedWorldId?: WorldId) {
    const childInput = text.trim();
    if (!childInput) return;
    const worldId = forcedWorldId ?? snapshot.activeWorldId;
    const world = worlds[worldId];
    const worldState = snapshot.worlds[worldId];
    const result = runMockAiTurn({ input: childInput, activeWorldId: worldId, currentState: worldState });
    const completedTaskIds = world.tasks
      .filter((task) => !snapshot.completedTaskIds.includes(task.id) && task.doneWhen.every((tag) => result.sparkTags.includes(tag)))
      .map((task) => task.id);
    const event: ChildEvent = { id: `event-${Date.now()}`, at: new Date().toISOString(), worldId, ageBand: snapshot.ageBand, childInput, aiReply: result.reply, safetyLevel: result.safetyLevel, sparkTags: result.sparkTags, worldDelta: result.worldDelta, completedTaskIds };
    updateSnapshot((current) => ({ ...current, activeWorldId: worldId, worlds: { ...current.worlds, [worldId]: { ...current.worlds[worldId], ...result.worldDelta } }, sparkScores: applySpark(current.sparkScores, result.sparkTags), completedTaskIds: Array.from(new Set([...current.completedTaskIds, ...completedTaskIds])), events: [event, ...current.events].slice(0, 100) }));
    setInput("");
  }
  function runScenario(scenario: PlaytestScenario) {
    submitTurn(scenario.sampleInput, scenario.worldId);
    setMode("play");
  }
  function resetExperience() {
    setSnapshot({ ...resetSnapshot(), worlds: initialWorldStates });
  }
  async function handleCloudSync() {
    const next = { ...snapshot, cloudSyncEnabled: !snapshot.cloudSyncEnabled };
    setSnapshot(next);
    setSyncMessage((await syncToCloudAdapter(next)).message);
  }
  return (
    <main className="appShell">
      <aside className="leftRail">
        <div className="brandMark"><span className="brandDot" /><div><strong>火火兔 Spark</strong><small>可玩内测版</small></div></div>
        <div className="segmented three"><button className={mode === "play" ? "selected" : ""} onClick={() => setMode("play")}>儿童游玩</button><button className={mode === "parent" ? "selected" : ""} onClick={() => setMode("parent")}>家长报告</button><button className={mode === "test" ? "selected" : ""} onClick={() => setMode("test")}>内测路线</button></div>
        <section className="railSection"><h2>年龄模式</h2>{ageBands.map((age) => <button key={age.id} className={snapshot.ageBand === age.id ? "ageButton active" : "ageButton"} onClick={() => updateSnapshot((current) => ({ ...current, ageBand: age.id }))}><span>{age.label}</span><small>{age.note}</small></button>)}</section>
        <section className="railSection"><h2>世界</h2>{(Object.keys(worlds) as WorldId[]).map((worldId) => <button key={worldId} className={snapshot.activeWorldId === worldId ? "worldButton active" : "worldButton"} onClick={() => updateSnapshot((current) => ({ ...current, activeWorldId: worldId }))}><span>{worlds[worldId].name}</span><small>{worlds[worldId].intent}</small></button>)}</section>
        <button className="quietButton" onClick={resetExperience}>重置本机体验</button>
      </aside>
      {mode === "play" ? (
        <section className="playSurface">
          <header className="playHeader"><div><p>{activeWorld.companion} · {activeWorld.companionRole}</p><h1>{activeWorld.name}</h1></div><div className="sparkPill"><span>最亮火花</span><strong>{sparkLabels[topSparkKey]}</strong></div></header>
          {!hasStarted ? <section className="firstRunCoach"><div><strong>第一次进入</strong><p>先选年龄和世界，然后点一个提示，或者让孩子说一句想法。世界会立刻回应，家长报告会同步记录。</p></div><button onClick={() => submitTurn(activeWorld.starterPrompts[0])}>开始第一句话</button></section> : null}
          <div className="worldScene" style={{ "--sky": activeWorld.palette.sky, "--ground": activeWorld.palette.ground, "--accent": activeWorld.palette.accent } as React.CSSProperties}>
            <div className="sun" /><div className="cloud cloudOne" /><div className="cloud cloudTwo" /><div className="land" />
            {activeWorldState.objects.slice(-7).map((object, index) => <button className={`worldObject object${index + 1}`} key={`${object}-${index}`} onClick={() => submitTurn(`我摸了摸${object}`)}>{object}</button>)}
            <div className="companionBubble"><strong>{activeWorld.companion}</strong><span>{activeWorldState.companionMood}</span></div>
          </div>
          <div className="playGrid">
            <section className="taskPanel"><div className="panelTitle"><h2>今日任务</h2><span>{completedInWorld}/{currentTasks.length}</span></div>{currentTasks.map((task) => <article key={task.id} className={snapshot.completedTaskIds.includes(task.id) ? "task done" : "task"}><strong>{task.title}</strong><p>{task.prompt}</p><small>{task.reward}</small></article>)}</section>
            <section className="talkPanel"><div className="panelTitle"><h2>对世界说话</h2><span>{activeWorldState.weather}</span></div><div className="promptChips">{activeWorld.starterPrompts.map((prompt) => <button key={prompt} onClick={() => submitTurn(prompt)}>{prompt}</button>)}</div><div className="promptChips secondary">{activeWorld.tactileActions.map((action) => <button key={action} onClick={() => submitTurn(action)}>{action}</button>)}</div><form className="inputRow" onSubmit={(event) => { event.preventDefault(); submitTurn(input); }}><input value={input} onChange={(event) => setInput(event.target.value)} placeholder={`孩子可以输入一句话，例如：${activeWorld.starterPrompts[0]}`} /><button type="submit">送进世界</button></form><div className={snapshot.events[0]?.safetyLevel === "redirected" ? "aiReply safety" : "aiReply"}><strong>{snapshot.events[0]?.safetyLevel === "redirected" ? "安全重定向" : "世界反馈"}</strong><p>{snapshot.events[0]?.aiReply ?? "小火和泡泡船长正在等孩子说出第一个想法。"}</p></div></section>
          </div>
        </section>
      ) : mode === "parent" ? (
        <section className="parentDashboard">
          <header className="dashboardHeader"><div><p>本地成长报告</p><h1>孩子的 Spark 轨迹</h1></div><button className="primaryAction" onClick={handleCloudSync}>{snapshot.cloudSyncEnabled ? "关闭云端队列" : "开启云端队列"}</button></header>
          <section className="reportSummary"><h2>{sparkLabels[topSparkKey]}</h2><p>{summarizeSpark(snapshot.events, snapshot.sparkScores)}</p><small>{syncMessage}</small></section>
          <section className="sparkBars">{sparkOrder.map((key) => <div className="sparkRow" key={key}><span>{sparkLabels[key]}</span><div className="barTrack"><div className="barFill" style={{ width: `${snapshot.sparkScores[key]}%` }} /></div><strong>{snapshot.sparkScores[key]}</strong></div>)}</section>
          <section className="eventStream"><div className="panelTitle"><h2>最近世界片段</h2><span>{snapshot.events.length} 条</span></div>{snapshot.events.length === 0 ? <p className="emptyText">还没有记录。开始游玩后，这里会显示孩子说过的话、世界反馈和 Spark 标签。</p> : snapshot.events.slice(0, 10).map((event) => <article className="eventItem" key={event.id}><div><strong>{worlds[event.worldId].shortName}</strong><span>{new Date(event.at).toLocaleString()}</span></div><p>孩子说：{event.childInput}</p><small>{event.sparkTags.map((tag) => sparkLabels[tag]).join(" · ")}</small></article>)}</section>
        </section>
      ) : (
        <section className="parentDashboard">
          <header className="dashboardHeader"><div><p>内部试玩</p><h1>内测路线</h1></div><button className="primaryAction" onClick={() => setMode("play")}>开始试玩</button></header>
          <section className="reportSummary"><h2>交互检查</h2><p>按下面四条路线跑完，即可判断这个版本是否已经是可直接玩的内测版。</p></section>
          <section className="testGrid">{playtestScenarios.map((scenario) => <article className="testCard" key={scenario.id}><strong>{scenario.title}</strong><p>{scenario.sampleInput}</p><small>{scenario.expected.join(" · ")}</small><button onClick={() => runScenario(scenario)}>跑这条</button></article>)}</section>
          <section className="eventStream"><div className="panelTitle"><h2>内测通过项</h2><span>{playtestChecks.filter((check) => check.ok).length}/{playtestChecks.length}</span></div>{playtestChecks.map((check) => <article className={check.ok ? "checkItem ok" : "checkItem"} key={check.label}>{check.ok ? "通过" : "待测"} · {check.label}</article>)}</section>
        </section>
      )}
    </main>
  );
}
"""


